import os
import torch


class Config:
    """
    Configuration for the Azimuthal-Channel 1D ResUNet with Squeeze-and-Excitation.
    """

    # --- Reproducibility ---
    SEED = 42

    # --- Compute ---
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Adjust workers based on available vCPUs (12 available)
    NUM_WORKERS = 4

    # --- Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Directories
    WORKING_DIR = "./working/idea_18"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    MODEL_DIR = os.path.join(WORKING_DIR, "models")
    SUBMISSION_DIR = "./submission"

    # Ensure output directories exist
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(MODEL_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # --- Data Preprocessing: Sky Panorama ---
    # Azimuthal sectors (360 / 8 = 45 degrees per bin)
    NUM_AZIMUTH_BINS = 8

    # Features calculated per azimuthal bin:
    # 1. Max Cn0
    # 2. Mean Elevation
    # 3. Satellite Count
    FEATURES_PER_BIN = 3

    # Global features (across all satellites):
    # 1-4. Cn0 (Mean, Std, Min, Max)
    # 5-8. Elevation (Mean, Std, Min, Max)
    # 9. Total Satellite Count
    # 10. Mean RawPseudorangeUncertainty
    NUM_GLOBAL_FEATURES = 10

    # Total Input Channels = (Bins * Feats/Bin) + Global
    # 8 * 3 + 10 = 34 channels
    INPUT_CHANNELS = (NUM_AZIMUTH_BINS * FEATURES_PER_BIN) + NUM_GLOBAL_FEATURES

    # Temporal Window Size for Training (in seconds/steps)
    # The model processes a sequence of this length
    TRAIN_WINDOW_SIZE = 256

    # --- Model Architecture: 1D SE-ResUNet ---
    # Channel dimensions for the Encoder stages
    ENCODER_CHANNELS = [64, 128, 256, 512]
    # Channel dimensions for the Decoder stages
    DECODER_CHANNELS = [256, 128, 64, 32]

    KERNEL_SIZE = 3
    # Squeeze-and-Excitation reduction ratio
    SE_REDUCTION = 16
    # Atrous Spatial Pyramid Pooling dilation rates
    ASPP_RATES = [1, 6, 12, 18]

    # --- Training Hyperparameters ---
    BATCH_SIZE = 32
    EPOCHS = 30
    LEARNING_RATE = 1e-3
    # Weight decay for AdamW
    WEIGHT_DECAY = 1e-4
    # Gradient clipping max norm
    GRADIENT_CLIP = 1.0

    # Deep Supervision Weights
    # Loss = 1.0 * Final_Head + 0.5 * Aux_Head_1 + 0.25 * Aux_Head_2
    DEEP_SUPERVISION_WEIGHTS = [1.0, 0.5, 0.25]

    # Early Stopping Patience
    PATIENCE = 8

    # --- WGS84 Constants ---
    # Used for converting Cartesian offsets (Meters) back to Geodetic offsets (Degrees)
    WGS84_A = 6378137.0  # Semi-major axis
    WGS84_B = 6356752.314245  # Semi-minor axis

    # --- Debugging ---
    # If True, runs on a small subset of data for quick pipeline verification
    DEBUG = False
